function randCoord(w, h, pad){ return { x: pad + Math.random() * (w - 2 * pad), y: pad + Math.random() * (h - 2 * pad) }; }
function hitTest(px, py, tx, ty, tr){ var dx = px - tx, dy = py - ty; return dx * dx + dy * dy <= tr * tr; }
function rating(acc){
  if (acc >= 0.95) return "神射手";
  if (acc >= 0.8) return "高手";
  if (acc >= 0.6) return "熟练";
  if (acc >= 0.4) return "新手";
  return "继续练习";
}
var EXPORTS = { randCoord: randCoord, hitTest: hitTest, rating: rating };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AimForgePure = EXPORTS; }
